"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["29813"],{24504(e){e.exports=JSON.parse('{"tag":{"label":"Breeds","permalink":"/docs/tags/breeds","allTagsPath":"/docs/tags","count":7,"items":[{"id":"Rats/breeds-and-genetics/rat-variety-guide","title":"A Guide to Fancy Rat Varieties","description":"Welcome to the colorful world of fancy rats! Through selective breeding, pet rats have been developed in a stunning array of colors, coat types, and markings. While these varieties are fascinating,...","permalink":"/docs/Rats/breeds-and-genetics/rat-variety-guide"},{"id":"guinea-pigs/breeds-and-genetics/know-your-guinea-pig-breeds","title":"Know Your Guinea Pig Breeds","description":"From the sleek and smooth to the curly and long-haired, guinea pigs come in a wonderful variety of breeds, each with its own unique look and grooming needs. While personality is individual, some...","permalink":"/docs/guinea-pigs/breeds-and-genetics/know-your-guinea-pig-breeds"},{"id":"Hamsters/breeds-and-genetics/know-your-hamster-breeds","title":"Know Your Hamster Breeds","description":"An overview of the five hamster species commonly kept as pets, with their key traits, size, and care considerations.","permalink":"/docs/Hamsters/breeds-and-genetics/know-your-hamster-breeds"},{"id":"Rabbits/breeds-and-genetics/know-your-rabbit-breeds","title":"Know Your Rabbit Breeds","description":"A guide to popular pet rabbit breeds recognized by the American Rabbit Breeders Association, including size, temperament, and care considerations.","permalink":"/docs/Rabbits/breeds-and-genetics/know-your-rabbit-breeds"},{"id":"Rabbits/illnesses-and-conditions/maxfactor","title":"Max Factor Rabbits","description":"Max Factor rabbits are a rare and unique type of rabbit affected by a genetic mutation that results in unusual physical characteristics. These rabbits have striking appearances due to differences in their fur and limbs. It\u2019s said that the condition is named after a rabbit named Max who was known to have the condition, but not much is known about the defect or its origin. However, the mutation also affects their health and mobility, creating both challenges and specific care needs. Here\u2019s everything you need to know about Max Factor rabbits, from their characteristics to the ethics of breeding them.","permalink":"/docs/Rabbits/illnesses-and-conditions/maxfactor"},{"id":"guinea-pigs/breeds-and-genetics/coat-color-genetics","title":"Understanding Guinea Pig Coat Color Genetics","description":"Guinea pigs are known for their stunning diversity of coat colors and patterns, from solid black to intricate brindles and dalmatians. This variety isn\'t random; it\'s the result of a fascinating and complex world of genetics. Understanding the basics of coat color inheritance is not only interesting for curious owners but is also critical for responsible breeding and rescue advocacy to prevent serious genetic health problems.","permalink":"/docs/guinea-pigs/breeds-and-genetics/coat-color-genetics"},{"id":"guinea-pigs/breeds-and-genetics/hairless-skinny-pigs","title":"What to Know about Hairless or \\"Skinny\\" Pigs","description":"Hairless guinea pigs, most commonly known as \\"Skinny Pigs,\\" are a unique and increasingly popular variety of cavy. Their striking appearance, lacking the typical fluffy coat, makes them stand out, but it also means they have specialized care requirements that potential owners must be prepared to meet. Understanding their unique needs is essential to providing them with a healthy and happy life.","permalink":"/docs/guinea-pigs/breeds-and-genetics/hairless-skinny-pigs"}],"unlisted":false}}')}}]);